    /// <summary>
    ///     Finds the specified record in the <c>METDutyRollValuesTable</c> table.
    /// </summary>
    /// <param name = "_site">InventSiteId</param>
    /// <param name = "_forUpdate">true/false</param>
    /// <returns>
    ///     A record in the <c>METDutyRollValuesTable</c> table.
    /// </returns>
    static METDutyRollValuesTable find(InventSiteId _site, boolean _forUpdate = false)
    {
        METDutyRollValuesTable dutyRollValuesTable;

        dutyRollValuesTable.selectForUpdate(_forUpdate);
        select firstonly dutyRollValuesTable
            index MainIdx
            where dutyRollValuesTable.Site == _site;

        return dutyRollValuesTable;
    }

    /// <summary>
    ///     Finds the specified record in the <c>METDutyRollValuesTable</c> table.
    /// </summary>
    /// <param name = "_site">InventSiteId</param>
    /// <param name = "_forUpdate">true/false</param>
    /// <returns>
    ///     A record in the <c>METDutyRollValuesTable</c> table.
    /// </returns>
    static METDutyRollValuesTable findActive(InventSiteId _site, boolean _forUpdate = false)
    {
        METDutyRollValuesTable dutyRollValuesTable;

        dutyRollValuesTable.selectForUpdate(_forUpdate);
        select firstonly dutyRollValuesTable
            index MainIdx
            order by StartDate desc
            where dutyRollValuesTable.Site == _site
            && dutyRollValuesTable.Status == METDutyRollStatus::Active;

        return dutyRollValuesTable;
    }

/// <summary>
/// Checks if a <c>METDutyRollValuesTable</c> record exists;
/// </summary>
/// <param name = "_site">InventSiteId</param>
/// <returns>
/// true if a <c>METDutyRollValuesTable</c> record exists; otherwise, false.
/// </returns>
public static boolean exist(InventSiteId _site)
{
    return (select firstonly RecId from METDutyRollValuesTable
        where METDutyRollValuesTable.Site == _site).RecId != 0;
}

/// <summary>
/// change status to Inactive
/// </summary>
public void inactivateRecord()
{
    this.EndDate    = endMth(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()));
    this.Status     = METDutyRollStatus::Inactive;
}
